SELECT COUNT(DISTINCT CASE WHEN DAYS_SINCE_LAST_LOGIN >= 90 AND NOT IS_DISABLED THEN USER_NAME END) AS "SEC_DORMANT_USERS" FROM (SELECT "USER_ID" AS USER_ID, "NAME" AS USER_NAME, "LOGIN_NAME" AS LOGIN_NAME, "DEFAULT_ROLE" AS DEFAULT_ROLE, "DEFAULT_WAREHOUSE" AS DEFAULT_WAREHOUSE, "TYPE" AS USER_TYPE, COALESCE("DISABLED", FALSE) AS IS_DISABLED, COALESCE("HAS_PASSWORD", FALSE) AS HAS_PASSWORD, COALESCE("HAS_RSA_PUBLIC_KEY", FALSE) AS HAS_RSA_PUBLIC_KEY, (TRY_TO_TIMESTAMP_NTZ("LAST_SUCCESS_LOGIN")) AS LAST_SUCCESS_LOGIN_AT, (TRY_TO_TIMESTAMP_NTZ("CREATED_ON")) AS CREATED_AT, (TRY_TO_TIMESTAMP_NTZ("DELETED_ON")) AS DELETED_AT, MAX((TRY_TO_TIMESTAMP_NTZ("LAST_SUCCESS_LOGIN"))) OVER () AS SNAPSHOT_AT, (CAST(CASE WHEN (86400) = 0 OR (86400) IS NULL THEN NULL ELSE CAST(((DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("LAST_SUCCESS_LOGIN")), MAX((TRY_TO_TIMESTAMP_NTZ("LAST_SUCCESS_LOGIN"))) OVER ()))) AS DECIMAL(38, 15)) / CAST((86400) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS DAYS_SINCE_LAST_LOGIN FROM users) AS base ORDER BY "SEC_DORMANT_USERS" DESC NULLS LAST LIMIT 100
